<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import { useRouter } from 'vue-router'
import { ArrowUpRight, Download, ChevronLeft, ChevronRight, Search } from 'lucide-vue-next'
import * as XLSX from 'xlsx'
import { capabilityFor } from '../capabilities'
import { catalog, categoryDefinitions } from '../prototype-store'
import { observations, regions, filterObservations, buildBenefitMatrix, summarize, statusLabels, type Decision } from '../domain'
const router=useRouter(),from=ref('2026-08-01'),to=ref('2026-10-29'),region=ref(''),category=ref(''),search=ref(''),metric=ref('all'),page=ref(1),size=ref(8)
const keys=Object.keys(statusLabels) as Decision[]
const shortLabels:Record<Decision,string>={used:'Foydalangan',unused:'Foydalanmagan',mismatch:'Nomuvofiq',unknown:'Aniqlanmagan'}
const benefits=computed(()=>catalog.filter(b=>`${b.id} ${b.name}`.toLowerCase().includes(search.value.toLowerCase())))
const shown=computed(()=>benefits.value.slice((page.value-1)*size.value,page.value*size.value))
const names=computed(()=>categoryDefinitions.filter(c=>!category.value||c.name===category.value).map(c=>c.name))
const filtered=computed(()=>filterObservations(observations,{from:from.value,to:to.value,region:region.value,category:category.value,benefitId:0,status:'',search:'',gender:'',registry:''}))
const matrix=computed(()=>buildBenefitMatrix(filtered.value,names.value,benefits.value.map(b=>b.id)))
const empty=summarize([])
const cell=(name:string,id:number)=>matrix.value.cells.get(JSON.stringify([name,id]))??empty
const linked=(name:string,id:number)=>categoryDefinitions.find(c=>c.name===name)?.benefitIds.includes(id)??false
const statuses=computed(()=>metric.value==='all'?keys:[metric.value as Decision])
watch([from,to,region,category,search,size],()=>page.value=1)
function drill(name:string,id:number,status=''){router.push({path:'/apps/social-benefits/usage',query:{category:name,benefit:String(id),status,from:from.value,to:to.value,region:region.value}})}
function reset(){from.value='2026-08-01';to.value='2026-10-29';region.value='';category.value='';search.value='';metric.value='all';page.value=1}
function exportMatrix(){
 const data=names.value.map(name=>{const t=matrix.value.rowTotals.get(name)??empty;const row:Record<string,string|number>={Kontingent:name,'Jami shaxslar':t.people,'Jami foydalanishlar':t.events};for(const b of benefits.value){const c=cell(name,b.id);row[b.id+' · '+b.name]=c.people?(metric.value==='all'?keys.map(s=>shortLabels[s]+': '+c[s]).join('; '):c[metric.value as Decision]):linked(name,b.id)?'Ma’lumot yo‘q':'Bog‘lanmagan'}return row})
 const total:Record<string,string|number>={Kontingent:'JAMI','Jami shaxslar':matrix.value.total.people,'Jami foydalanishlar':matrix.value.total.events}
 for(const b of benefits.value){const t=matrix.value.columnTotals.get(b.id)??empty;total[b.id+' · '+b.name]=t.people+' shaxs; '+t.events+' foydalanish'}
 const book=XLSX.utils.book_new();XLSX.utils.book_append_sheet(book,XLSX.utils.json_to_sheet([total,...data]),'Matritsa');XLSX.utils.book_append_sheet(book,XLSX.utils.json_to_sheet([{Izoh:'NAMUNAVIY MA’LUMOT — frontend prototip',Davr:from.value+' — '+to.value,Hudud:region.value||'Barchasi',Kontingent:category.value||'Barchasi',Qidiruv:search.value,Holat:metric.value==='all'?'Barcha holatlar':statusLabels[metric.value as Decision],Hisob:'Shaxslar umumiy natijada takrorlanmaydi.'}]),'Filtrlar');XLSX.writeFile(book,'Kontingent_imtiyoz_matritsasi.xlsx')
}
</script>
<template>
<section class="mx-panel"><div class="mx-filters"><label>Davr boshi<input type="date" v-model="from" /></label><label>Davr oxiri<input type="date" v-model="to" /></label><label>Hudud<select v-model="region" aria-label="Matritsa hududi"><option value="">Barcha hududlar</option><option v-for="r in regions" :key="r">{{ r }}</option></select></label><label>Kontingent<select v-model="category" aria-label="Matritsa kontingenti"><option value="">Barcha kontingentlar</option><option v-for="c in categoryDefinitions" :key="c.name">{{ c.name }}</option></select></label><label>Katakdagi ko‘rsatkich<select v-model="metric" aria-label="Matritsa holati"><option value="all">Barcha holatlar</option><option v-for="s in keys" :key="s" :value="s">{{ statusLabels[s] }}</option></select></label><button @click="reset">Tozalash</button><button @click="exportMatrix" :disabled="!benefits.length||from>to"><Download :size="15" /> Excel</button></div><p v-if="from>to" class="mx-error" role="alert">Davr oxiri boshlanishidan oldin bo‘lishi mumkin emas.</p></section>
<div class="mx-stats"><div><span>Takrorlanmas shaxslar</span><b>{{ matrix.total.people }}</b><small>{{ matrix.total.families }} oila</small></div><div class="metric-good"><span>Foydalanish hodisalari</span><b>{{ matrix.total.events }}</b><small>Manba identifikatori bilan</small></div><div :class="matrix.total.unused>0?'metric-danger':'metric-good'"><span>Huquqi bor, foydalanmagan</span><b>{{ matrix.total.unused }}</b><small>Baholash yozuvlari</small></div><div :class="matrix.total.mismatch>0?'metric-danger':'metric-warning'"><span>Nazorat / aniqlashtirish</span><b>{{ matrix.total.mismatch }} / {{ matrix.total.unknown }}</b><small>Nomuvofiq / ma’lumot yetishmagan</small></div></div>
<section class="mx-panel mx-main"><div class="mx-heading"><label class="mx-search"><Search :size="15" /><input v-model="search" placeholder="Imtiyoz nomi yoki raqami bo‘yicha qidirish" aria-label="Matritsadan imtiyoz qidirish" /></label><label class="mx-size">Ustunlar<select v-model.number="size" aria-label="Sahifadagi imtiyozlar soni"><option :value="8">8 ta</option><option :value="16">16 ta</option><option :value="catalog.length">Barchasi</option></select></label></div><div class="mx-legend"><span v-for="s in keys" :key="s" :class="s"><i />{{ shortLabels[s] }}</span></div>
<div class="mx-scroll" tabindex="0" role="region" aria-label="Kontingent va imtiyozlar matritsasi"><table><caption class="sr-only">Kontingentlar qatorlarda, imtiyozlar ustunlarda, kataklarda davr bo‘yicha baholash holatlari</caption><thead><tr><th class="mx-corner" scope="col"><b>Kontingentlar ↓</b><span>Imtiyozlar →</span></th><th class="mx-total-head" scope="col">Qator bo‘yicha jami<small>Takrorlanmas hisob</small></th><th v-for="b in shown" :key="b.id" scope="col" :title="b.name"><small>IMTIYOZ {{ String(b.id).padStart(3,'0') }}</small><span v-if="capabilityFor(b.id).eligibility!=='auto'||capabilityFor(b.id).usage!=='auto'" class="mx-source-warning">Tekshiruv cheklangan</span><details><summary>{{ b.name }}</summary><p>{{ b.name }}</p></details></th></tr></thead><tbody><tr v-if="shown.length" class="mx-grand-total"><th class="mx-row-title" scope="row">Ustun bo‘yicha jami<small>Shaxslar / foydalanishlar</small></th><td class="mx-row-total"><b>{{ matrix.total.people }} shaxs</b><span>{{ matrix.total.events }} foydalanish</span></td><td v-for="b in shown" :key="b.id"><b>{{ (matrix.columnTotals.get(b.id)??empty).people }} shaxs</b><span>{{ (matrix.columnTotals.get(b.id)??empty).events }} foydalanish</span></td></tr><tr v-for="name in names" :key="name"><th class="mx-row-title" scope="row"><b>{{ name }}</b><small>{{ categoryDefinitions.find(c=>c.name===name)?.code }}</small></th><td class="mx-row-total"><b>{{ (matrix.rowTotals.get(name)??empty).people }}</b><small>shaxs</small><span>{{ (matrix.rowTotals.get(name)??empty).events }} foydalanish</span></td><td v-for="b in shown" :key="b.id" :class="{'mx-no-data':!cell(name,b.id).people,'mx-risk-cell':cell(name,b.id).mismatch>0}"><template v-if="cell(name,b.id).people"><button class="mx-cell-title" @click="drill(name,b.id)" :aria-label="`${name}, ${b.id}-imtiyoz: ${cell(name,b.id).people} shaxs. Ro‘yxatni ochish`"><b>{{ cell(name,b.id).people }}</b> shaxs <ArrowUpRight :size="12" /></button><div class="mx-status-list"><button v-for="s in statuses" :key="s" :class="s" :disabled="!cell(name,b.id)[s]" @click="drill(name,b.id,s)" :aria-label="`${name}, ${b.id}-imtiyoz: ${statusLabels[s]} ${cell(name,b.id)[s]}`"><span>{{ shortLabels[s] }}</span><b>{{ cell(name,b.id)[s] }}</b></button></div></template><div v-else class="mx-empty-cell"><span>—</span><small>{{ linked(name,b.id)?'Ma’lumot yo‘q':'Bog‘lanmagan' }}</small></div></td></tr><tr v-if="!shown.length"><td :colspan="shown.length+2">Qidiruvga mos imtiyoz topilmadi.</td></tr></tbody></table></div>
<div class="mx-footer"><span>{{ benefits.length }} ta imtiyozdan {{ benefits.length?(page-1)*size+1:0 }}–{{ Math.min(page*size,benefits.length) }} ko‘rsatilmoqda</span><button :disabled="page===1" @click="page--"><ChevronLeft :size="15" /> Oldingi</button><b>{{ page }} / {{ Math.max(1,Math.ceil(benefits.length/size)) }}</b><button :disabled="page*size>=benefits.length" @click="page++">Keyingi <ChevronRight :size="15" /></button></div><details class="mx-note"><summary>Hisoblash tartibi</summary><div><b>Hisoblash izohi.</b> Katakdagi holatlar — tanlangan davrdagi baholash yozuvlari soni. Bir shaxs bir nechta kontingent va imtiyozda qatnashishi mumkin; umumiy shaxslar soni qayta takrorlanmas hisoblanadi. Shu sabab qatorlar yoki ustunlardagi shaxslar yig‘indisi umumiy natijaga teng bo‘lishi shart emas. Jami ko‘rsatkichlar qidiruvga mos barcha imtiyozlarni qamrab oladi, faqat joriy ustun sahifasini emas. “Ma’lumot yo‘q” foydalanmaganlikni anglatmaydi.</div></details></section>
</template>
<style scoped src="./benefits-matrix.css"></style>
